import { NextRequest, NextResponse } from "next/server";
import { generateText } from "ai";
import { createOpenAI } from "@ai-sdk/openai";

const openai = createOpenAI({
    baseURL: process.env.OPENAI_BASE_URL!,
    apiKey: process.env.OPENAI_API_KEY!,
});

export async function POST(req: NextRequest) {
    const { prompt, system } = await req.json();
    const result = await generateText({
        model: openai('openai'),
        system: system,
        prompt: prompt,
    });

    const lines = result.text.split('\n').filter(line => line.trim() !== '');
    return NextResponse.json(lines)
}

import { NextRequest, NextResponse } from "next/server";
import { Client } from "@gradio/client";

const client = await Client.connect(process.env.CLIENT_TTS!);

export async function POST(req: NextRequest) {
    const { line, voice, emotion } = await req.json();
    const result = await client.predict("/text_to_speech_app", { 
        prompt: line.replace("Munna Bhai:", "").replace("Circuit:", ""), 		
        voice: voice, 		
        emotion: emotion, 		
        use_random_seed: true, 		
        specific_seed: 3, 
    });
    return NextResponse.json(result)
}

'use client'

import React, { useState, useEffect, useCallback } from 'react';
import { Player } from '@remotion/player';
import { MyVideo } from './Video';
import { getAudioDuration } from '../utils/audioUtils';
import { SYSTEM_PROMPT_MUNNA_CIRCUIT } from '@/constants';

const Page = () => {
    const [lines, setLines] = useState<string[]>([]);
    const [audios, setAudios] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isRendering, setIsRendering] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [prompt, setPrompt] = useState('');
    const [videoData, setVideoData] = useState<Array<{
        speaker: 'Munna Bhai' | 'Circuit';
        text: string;
        audioUrl: string;
        durationInFrames: number;
    }>>([]);
    const [showPlayer, setShowPlayer] = useState(false);

    const fetchData = async () => {
        setIsLoading(true);
        try {
                const chatResponse = await fetch("/api/chat", {
                    method: "POST",
                    body: JSON.stringify({
                        system: SYSTEM_PROMPT_MUNNA_CIRCUIT,
                        prompt: prompt,
                    }),
                });
                const chatLines = await chatResponse.json();
                setLines(chatLines);

                // Generate audio for each line
                const audioPromises = chatLines.map(async (line: string, index: number) => {
                    const { voice } = getSpeakerVoice(line);
                    const isLastLine = index === chatLines.length - 1;
                    const emotion = isLastLine ? 'excited' : getSpeakerEmotion(line).emotion;
                    const audioRes = await fetch("/api/tts", {
                        method: "POST",
                        body: JSON.stringify({
                            line: line.replace("Munna Bhai:", "").replace("Circuit:", ""),
                            voice: voice,
                            emotion: emotion,
                            use_random_seed: true,
                            specific_seed: 3,
                        }),
                    });
                    return audioRes.json();
                });

                const audioResults = await Promise.all(audioPromises);
                setAudios(audioResults);

                // Prepare video data with durations
                const videoData = await Promise.all(chatLines.map(async (line: string, index: number) => {
                    const speaker = line.startsWith('Munna Bhai:') ? 'Munna Bhai' : 'Circuit';
                    const audioUrl = audioResults[index].data[0].url || '';
                    const durationInFrames = audioUrl ? await getAudioDuration(audioUrl) : 90; // 3 seconds default

                    return {
                        speaker: speaker as 'Munna Bhai' | 'Circuit',
                        text: line.replace('Munna Bhai:', '').replace('Circuit:', '').trim(),
                        audioUrl: audioUrl,
                        durationInFrames: durationInFrames
                    };
                }));

                setVideoData(videoData);
            } catch (err) {
                setError('Failed to load content. Please try again.');
                console.error('Error:', err);
            } finally {
                setIsLoading(false);
            }
        };

    const getSpeakerVoice = (line: string): { speaker: string, voice: string } => {
        if (line.startsWith('Munna Bhai:')) {
            return { speaker: 'Munna Bhai', voice: 'dan' };
        } else if (line.startsWith('Circuit:')) {
            return { speaker: 'Circuit', voice: 'ballad' };
        } else {
            return { speaker: 'Unknown', voice: 'shimmer' };
        }
    };

    const getSpeakerEmotion = (line: string): { speaker: string, emotion: string } => {
        if (line.startsWith('Munna Bhai:')) {
            return { speaker: 'Munna Bhai', emotion: 'confidentaly' };
        } else if (line.startsWith('Circuit:')) {
            return { speaker: 'Circuit', emotion: 'questionary & confused' };
        } else {
            return { speaker: 'Unknown', emotion: 'excited' };
        }
    };


    const handleRenderVideo = useCallback(() => {
        try {
            const dataToSend = videoData.map(item => ({
                ...item,
                // Ensure all required fields are present and have proper types
                speaker: item.speaker as 'Munna Bhai' | 'Circuit',
                text: item.text || '',
                audioUrl: item.audioUrl || '',
                durationInFrames: Number(item.durationInFrames) || 90
            }));

            const url = `/test/video?data=${encodeURIComponent(JSON.stringify(dataToSend))}`;
            window.open(url, '_blank');
        } catch (error) {
            console.error('Error preparing video data:', error);
            setError('Failed to prepare video data. Please try again.');
        }
    }, [videoData]);

    if (isLoading) {
        return <div className="p-4">Loading...</div>;
    }

    if (error) {
        return <div className="p-4 text-red-500">{error}</div>;
    }

    return (
        <div className="min-h-screen bg-gray-900 p-8">
            <div className="max-w-4xl mx-auto">
                <h1 className="text-3xl font-bold mb-6">Munna Bhai & Circuit AI</h1>

                <div className="mb-6">
                    <input
                        type="text"
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        placeholder="Enter your prompt..."
                        className="w-full p-2 border rounded"
                    />
                    <div className="flex gap-2 mt-2">
                        <button
                            onClick={fetchData}
                            disabled={isLoading}
                            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 disabled:bg-gray-400"
                        >
                            {isLoading ? 'Generating...' : 'Generate Conversation'}
                        </button>
                        {videoData.length > 0 && (
                            <button
                                onClick={handleRenderVideo}
                                disabled={isRendering}
                                className="px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600 disabled:bg-gray-400"
                            >
                                {isRendering ? 'Rendering...' : 'Render Video'}
                            </button>
                        )}
                    </div>
                </div>

                {error && <div className="text-red-500 mb-4">{error}</div>}

                <div className="space-y-4 mb-8">
                    {lines.map((line, index) => (
                        <div key={index} className="p-4 bg-gray-800 rounded shadow">
                            <p className="font-semibold">{line.split(':')[0]}:</p>
                            <p>{line.split(':').slice(1).join(':').trim()}</p>
                            {audios[index]?.data?.[0]?.url && (
                                <audio
                                    controls
                                    src={audios[index].data[0].url}
                                    className="mt-2 w-full"
                                />
                            )}
                        </div>
                    ))}
                </div>

                {showPlayer && videoData.length > 0 && (
                    <div className="bg-gray-800 p-4 rounded-lg shadow-lg">
                        <h2 className="text-xl font-bold mb-4">Generated Video</h2>
                        <div className="aspect-video w-full bg-black rounded overflow-hidden">
                            <Player
                                component={MyVideo}
                                inputProps={{ 
                                    data: videoData.map(item => ({
                                        ...item,
                                        speaker: item.speaker as 'Munna Bhai' | 'Circuit',
                                        text: item.text || '',
                                        audioUrl: item.audioUrl || '',
                                        durationInFrames: Number(item.durationInFrames) || 90
                                    }))
                                }}
                                durationInFrames={videoData.reduce((sum, item) => sum + (Number(item.durationInFrames) || 90), 0)}
                                fps={30}
                                compositionWidth={1080}
                                compositionHeight={1920}
                                style={{
                                    width: '100%',
                                    height: '100%',
                                }}
                                controls
                                loop
                            />
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Page;

import { Audio, Img, Sequence, AbsoluteFill, useVideoConfig, useCurrentFrame, interpolate } from 'remotion';

type WordType = {
  text: string;
  opacity: number;
};

type ConversationVideoProps = {
  speaker: 'Munna Bhai' | 'Circuit';
  text: string;
  audioUrl: string;
  durationInFrames: number;
};

export const ConversationVideo = ({
  speaker,
  text,
  audioUrl,
  durationInFrames,
}: ConversationVideoProps) => {
  const { width, height } = useVideoConfig();
  const frame = useCurrentFrame();
  const imagePath = speaker === 'Circuit' ? '/circuit.png' : '/munna.png';

  // Split text into words and create animation states
  const words = text.split(' ');
  const wordDuration = 5; // frames per word

  // Create animated words
  const animatedWords = words.map((word, i) => {
    const startFrame = i * wordDuration;
    const endFrame = startFrame + wordDuration;
    const opacity = interpolate(
      frame,
      [startFrame, startFrame + 1, endFrame - 1, endFrame],
      [0, 1, 1, 0],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
    );
    return { text: word, opacity };
  });

  return (
    <Sequence durationInFrames={durationInFrames}>
      <AbsoluteFill>
        {/* Content Overlay */}
        <AbsoluteFill
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'white',
            width: '100%',
            height: '100%',
            zIndex: 1,
          }}
        >
          <Img
            src={imagePath}
            style={{
              width: Math.min(500, width * 0.8),
              borderRadius: '8px',
              boxShadow: '0 4px 8px rgba(0,0,0,0.1)',
            }}
          />
          <div
            style={{
              fontSize: Math.min(40, width * 0.04),
              marginTop: 40,
              maxWidth: Math.min(900, width * 0.9),
              textAlign: 'center',
              padding: '0 20px',
              lineHeight: 1.4,
              minHeight: '3em',
              display: 'flex',
              flexWrap: 'wrap',
              justifyContent: 'center',
              gap: '0.2em',
            }}
          >
            {animatedWords.map((word, i) => (
              <span
                key={i}
                style={{
                  display: 'inline-block',
                  transform: `translateY(${10 * (1 - word.opacity)}px)`,
                  transition: 'all 0.2s ease-out',
                }}
              >
                {word.text}{' '}
              </span>
            ))}
          </div>
          {audioUrl && <Audio src={audioUrl} volume={1} />}
        </AbsoluteFill>
      </AbsoluteFill>
    </Sequence>
  );
};

import { AbsoluteFill, Sequence, useVideoConfig, Video } from 'remotion';
import { ConversationVideo } from './ConversationVideo';

export type VideoData = {
  speaker: 'Munna Bhai' | 'Circuit';
  text: string;
  audioUrl: string;
  durationInFrames: number;
};

type MyVideoProps = {
  data: VideoData[];
};

export const MyVideo = ({ data }: MyVideoProps) => {
  const { fps } = useVideoConfig();
  let currentFrame = 0;

  // Calculate total duration for the background video
  const totalDuration = data.reduce((sum, line) => sum + line.durationInFrames, 0);

  return (
    <>
      {/* Background Video - Single instance at the root level */}
      <AbsoluteFill>
        <div style={{ width: '100%', height: '100%', position: 'relative' }}>
          <Video 
            src="/bg.mp4" 
            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
            volume={0.2}
            playbackRate={0.8}
            muted
            loop
          />
        </div>
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.5)',
        }} />
      </AbsoluteFill>

      {/* Conversation Sequences */}
      {data.map((line, i) => {
        const startFrame = currentFrame;
        const duration = line.durationInFrames;
        currentFrame += duration;

        return (
          <Sequence key={i} from={startFrame} durationInFrames={duration}>
            <ConversationVideo 
              speaker={line.speaker} 
              text={line.text} 
              audioUrl={line.audioUrl} 
              durationInFrames={duration} 
            />
          </Sequence>
        );
      })}
    </>
  );
};

'use client';

import { Player } from '@remotion/player';
